// Normalize Gumroad ping (form-encoded) into clean fields.
const b = $input.first().json.body || $input.first().json;
const permalink = (b.permalink || b.short_url || '').split('/').pop();
const emails = {
  rsaiql: {
    subject: 'Getting a full week out of one transcript yet?',
    body: `Hey {{name}},

Thanks for picking up the Repurpose Kit. Quick tip most people miss: the prompt templates in prompts/*.md are meant to be edited — swap in a few phrases you actually use and the output stops sounding generic and starts sounding like you. Two minutes, big difference.

If the kit's saving you time, would you leave a quick rating? It genuinely helps a small tool like this get found: https://gumroad.com/library

Stuck on anything — install, API keys, mock mode — just reply and I'll help.

— Aaron`
  },
  cdvftz: {
    subject: 'One thing to do before reading past chapter 2',
    body: `Hey {{name}},

Thanks for grabbing the Playbook. Before you go deep: do the niche-scoring worksheet early. Almost everyone wants to skip to the listing templates, but ten minutes of scoring saves weeks of building in a niche that won't convert.

If it's been useful so far, a quick rating would mean a lot — reviews are how playbooks like this reach other sellers: https://gumroad.com/library

Questions about your niche pick? Reply — I read these.

— Aaron`
  },
  hjabq: {
    subject: 'The 10-minute brand-swap trick for your new templates',
    body: `Hey {{name}},

Thanks for picking up the Editorial Neutral bundle. Fastest way to make all 250 templates yours: open one template, set your two brand colors and fonts using Canva's Brand Kit, and every other template picks them up as you open it. Ten minutes, entire library on-brand.

If the templates are earning their keep on your feed, I'd really appreciate a quick rating: https://gumroad.com/library

Anything broken or missing? Reply and I'll fix it.

— Aaron`
  },
  mszpqt: {
    subject: "Which 10 reels to post first (don't start at #1)",
    body: `Hey {{name}},

Thanks for grabbing The Estate Reel. Tip: don't post in file order. Start with the "just listed" and "sold" hooks — they perform best for building an audience — and save the lifestyle/neighborhood clips for once you have some followers watching.

If the reels are getting you engagement, a quick rating helps other agents find the pack: https://gumroad.com/library

Want a posting-cadence suggestion for your market? Hit reply.

— Aaron`
  },
  oxgrh: {
    subject: 'Print just page 3 first',
    body: `Hey {{name}},

Thanks for getting the Daily Dashboard. Honest advice: don't print all 40 pages. Print the one-page daily sheet (page 3) five times and run just that for a week. If it sticks, add the weekly review page. Starting small is the whole trick.

If it's helping your days feel more manageable, a quick rating would mean a lot: https://gumroad.com/library

— Aaron

P.S. Reply if you'd like the undated pages as separate files for easier printing.`
  }
};
const tpl = emails[permalink] || { subject: `How's ${b.product_name || 'your purchase'} working for you?`, body: `Hey {{name}},

Thanks for your purchase! If it's been helpful, a quick rating would mean a lot: https://gumroad.com/library

— Aaron` };
const name = (b.full_name || '').split(' ')[0] || 'there';
return [{ json: {
  sale_id: b.sale_id || '',
  buyer_email: b.email || '',
  buyer_name: name,
  product_name: b.product_name || permalink,
  permalink,
  price_usd: (parseInt(b.price || 0, 10) / 100).toFixed(2),
  country: b.ip_country || 'unknown',
  sale_timestamp: b.sale_timestamp || new Date().toISOString(),
  email_subject: tpl.subject,
  email_body: tpl.body.replace('{{name}}', name)
}}];

